// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new W_WALLET(address(log_));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // Rule: a successful Put always appends a log entry recording the
        // deposited amount. With a fresh Log, that entry is History(0).
        // Reference: the read succeeds and Val == amount.
        // Mutant (AddMessage removed from Put): History is empty -> read fails.
        bool logged;
        uint256 loggedVal;
        try log_.History(0) returns (address, string memory, uint256 v, uint256) {
            logged = true;
            loggedVal = v;
        } catch {
            logged = false;
        }
        assertTrue(logged && loggedVal == amount);
    }
}
